package com.example.app02.application.service; import com.example.app02.domain.entity.InventoryItem; import com.example.app02.infrastructure.repository.InventoryItemRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class InventoryItemService { private final InventoryItemRepository repository; public InventoryItemService(InventoryItemRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<InventoryItem> list() { return repository.findAll(); } @Transactional public InventoryItem create(InventoryItem e) { return repository.save(e); } }
